import { Block, GENESIS_PREV_HASH, computeHash } from '../lib/block'
import { mineSync } from '../lib/mine'

export const SAMPLE_DIFFICULTY = 3

const SAMPLE_TEXTS = [
  'Genesis: the first block in the chain',
  'Alice buys a coffee',
  'Bob pays rent',
  'Carol sells a bicycle',
  'Dave donates to charity',
]

/** Pre-mined text chain, generated by mining at startup so nonces never go stale. */
export function buildTextSampleChain(difficulty = SAMPLE_DIFFICULTY): Block[] {
  const chain: Block[] = []
  SAMPLE_TEXTS.forEach((data, i) => {
    const prevHash = i === 0 ? GENESIS_PREV_HASH : chain[i - 1].hash
    const base = { index: i + 1, nonce: 0, data, prevHash }
    const nonce = mineSync(base, difficulty)
    chain.push({ ...base, nonce, hash: computeHash({ ...base, nonce }) })
  })
  return chain
}

/** A single block for the Block page: starts unmined (nonce 0). */
export function buildSingleBlock(): Block {
  const base = { index: 1, nonce: 0, data: 'Hello, blockchain!', prevHash: GENESIS_PREV_HASH }
  return { ...base, hash: computeHash(base) }
}
